begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
select lives_ok($$ select * from public.create_customer_visit('Aline','50000000-0000-4000-8000-000000000001') $$,'creates customer visit');
select is((select status::text from public.customer_visits where customer_name='Aline'),'AGUARDANDO_MESA','visit waits for table');
select ok((select token_hash<>convert_to('50000000-0000-4000-8000-000000000001','UTF8') from public.customer_visits where customer_name='Aline'),'stores token as hash');
select throws_ok($$ select * from public.create_customer_order('Aline','50000000-0000-4000-8000-000000000001','[{"product_id":"20000000-0000-4000-8000-000000000003","quantity":1}]','','50000000-0000-4000-8000-000000000011') $$,'CUSTOMER_AWAITING_TABLE','rejects order before table assignment');
select lives_ok($$ select * from public.assign_customer_visit((select id from public.customer_visits where customer_name='Aline'),2::smallint) $$,'admin assigns free table');
select is((select status::text from public.customer_visits where customer_name='Aline'),'MESA_ASSOCIADA','marks visit assigned');
select is((select status::text from public.restaurant_tables where number=2),'OCUPADA','marks assigned table occupied');
select lives_ok($$ select * from public.create_customer_visit('Bruno','50000000-0000-4000-8000-000000000002') $$,'creates competing visit');
select throws_ok($$ select * from public.assign_customer_visit((select id from public.customer_visits where customer_name='Bruno'),2::smallint) $$,'TABLE_NOT_FREE','prevents two visits on same table');
select lives_ok($$ select * from public.create_customer_order('Aline','50000000-0000-4000-8000-000000000001','[{"product_id":"20000000-0000-4000-8000-000000000003","quantity":1}]','','50000000-0000-4000-8000-000000000012') $$,'creates first assigned order');
select lives_ok($$ select * from public.create_customer_order('Aline','50000000-0000-4000-8000-000000000001','[{"product_id":"20000000-0000-4000-8000-000000000006","quantity":1}]','','50000000-0000-4000-8000-000000000013') $$,'creates second assigned order');
select is((select count(distinct session_id)::integer from public.orders where idempotency_key in ('50000000-0000-4000-8000-000000000012','50000000-0000-4000-8000-000000000013')),1,'reuses one table session');
select lives_ok($$ select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000012'),'CANCELADO') $$,'cancels one order');
select is((select status::text from public.customer_visits where customer_name='Aline'),'MESA_ASSOCIADA','isolated cancellation keeps visit open');
select lives_ok($$ select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000013'),'EM_PREPARO');select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000013'),'PRONTO');select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000013'),'ENTREGUE');select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000013'),'AGUARDANDO_PAGAMENTO');select public.transition_order_status((select id from public.orders where idempotency_key='50000000-0000-4000-8000-000000000013'),'PAGO') $$,'payment closes final order, session and visit');
select is((select status::text from public.customer_visits where customer_name='Aline'),'ENCERRADA','closes visit with table session');
select is((select status::text from public.restaurant_tables where number=2),'LIVRE','releases table after payment');
select lives_ok($$ select * from public.create_customer_visit('Aline','50000000-0000-4000-8000-000000000001') $$,'same token creates a new visit after closure');
select is((select count(*)::integer from public.customer_visits where customer_name='Aline'),2,'closed visit is preserved and not reused');
select throws_ok($$ select * from public.create_customer_order('Aline','50000000-0000-4000-8000-000000000001','[{"product_id":"20000000-0000-4000-8000-000000000003","quantity":1}]','','50000000-0000-4000-8000-000000000014') $$,'CUSTOMER_AWAITING_TABLE','closed visit cannot interfere with new waiting visit');
select * from finish();
rollback;
